import Foundation

/// A string from Localizable.xcstrings (generated by ios/scripts/generate-strings.py), formatted with positional
/// arguments when given. Keys are the Android string names.
func tr(_ key: String, _ arguments: CVarArg...) -> String {
    let format = Bundle.main.localizedString(forKey: key, value: nil, table: nil)
    return arguments.isEmpty ? format : String(format: format, locale: Locale.current, arguments: arguments)
}

/// The site/web-app language code of the localization the app runs in (the codes label42 and marks42 use).
/// The app's localizations are named like the site's languages (zh-Hans, zh-Hant, fil, id, pt, ...).
func siteLanguage(_ preferred: [String] = Bundle.main.preferredLocalizations) -> String {
    guard let first = preferred.first, first != "Base" else { return "en" }
    switch first {
    case "zh-Hans", "zh-Hant": return first
    case let code where code.hasPrefix("zh-HK") || code.hasPrefix("zh-TW") || code.hasPrefix("zh-MO"): return "zh-Hant"
    case let code where code.hasPrefix("zh"): return "zh-Hans"
    case let code where code.hasPrefix("pt"): return "pt"
    case "tl": return "fil"
    case "in": return "id"
    default: return String(first.split(separator: "-").first ?? "en")
    }
}
